components.css:
.ds-shortlist-stage { position:relative; isolation:isolate; background:var(--stage); padding:32px; border-radius:var(--radius-stage); min-height:462px; overflow:hidden; }
.ds-stage-top { display:flex; justify-content:space-between; align-items:center; gap:8px; font-size:12px; }
.ds-shortlist-tabs { margin-top:24px; display:flex; gap:4px; position:relative; z-index:1; }
.ds-shortlist-tabs button { padding:10px 12px; min-height:44px; font-size:11px; font-weight:600; color:#42573f; border-radius:6px; white-space:nowrap; transition:background var(--duration-ui),color var(--duration-ui); }
.ds-shortlist-tabs button:hover { background:rgba(255,255,255,.45); }
.ds-shortlist-tabs button[aria-pressed=true] { background:var(--ink); color:var(--surface); }
.ds-shortlist-sheet { position:relative; margin-top:20px; background:var(--surface); box-shadow:var(--shadow-raised); border-radius:12px; padding:24px; z-index:1; }

.ds-sheet-heading { display:flex; align-items:baseline; justify-content:space-between; gap:8px; padding-bottom:16px; }
.ds-sheet-heading h2 { font-size:16px; font-weight:650; letter-spacing:-.035em; }
.ds-sheet-heading>span { color:var(--muted); font-size:10px; }
.ds-shortlist-row { padding:16px 0; display:flex; align-items:center; gap:14px; border-top:1px solid #e9ece4; transition:color var(--duration-ui); }
.ds-shortlist-row:hover .ds-shortlist-detail strong { text-decoration:underline; }
.ds-shortlist-row>svg { margin-left:auto; flex-shrink:0; }
.ds-software-monogram { width:44px; height:44px; flex-shrink:0; display:grid; place-items:center; font-size:23px; font-weight:750; line-height:1; border-radius:11px; background:#e7eddf; color:#345239; }
.ds-tone-0 { background:#edf0d8; color:#667224; }
.ds-tone-1 { background:#fae4db; color:#aa4931; }
.ds-tone-2 { background:#e3eaf1; color:#365d7a; }
.ds-tone-3 { background:#e8e3f1; color:#665080; }
.ds-tone-4 { background:#e7e9df; color:#334238; }
.ds-shortlist-detail { display:flex; flex-direction:column; gap:5px; }
.ds-shortlist-detail strong { font-size:15px; font-weight:700; }
.ds-shortlist-detail>span { font-size:10px; color:var(--muted); }
.ds-sheet-link { display:flex; justify-content:space-between; align-items:center; border-top:1px solid var(--line); padding-top:16px; margin-top:0; font-size:11px; font-weight:650; min-height:40px; }
.ds-stage-note { display:flex; gap:16px; flex-wrap:wrap; margin-top:24px; font-size:9px; position:relative; z-index:1; }
.ds-stage-note>span { display:flex; align-items:center; gap:4px; }
.ds-stage-orbit { position:absolute; width:400px; height:400px; border:1px solid rgba(52,82,57,.12); border-radius:50%; right:-200px; top:120px; z-index:-1; }

.ds-shortlist-tabs button{font-size:12px}.ds-shortlist-detail>span{font-size:12px}.ds-sheet-heading>span,.ds-sheet-link,.ds-stage-note{font-size:11px}.ds-stage-note{gap:12px}
@media(max-width:1199px){.ds-shortlist-stage{padding:24px}.ds-shortlist-sheet{padding:20px}.ds-shortlist-tabs button{font-size:11px;padding-inline:8px}}
@media(min-width:700px) and (max-width:959px){.ds-shortlist-stage{padding:32px}.ds-shortlist-tabs button{font-size:13px}.ds-sheet-heading>span{display:none}}
@media(max-width:699px){.ds-shortlist-stage{padding:20px;min-height:auto;border-radius:16px}.ds-stage-top{font-size:11px}.ds-shortlist-tabs{gap:4px}.ds-shortlist-tabs button{flex:1;font-size:11px;padding:10px 7px}.ds-shortlist-sheet{padding:20px}.ds-sheet-heading h2{font-size:14px}.ds-sheet-heading>span{display:none}.ds-shortlist-row{gap:12px;padding-block:14px}.ds-shortlist-detail strong{font-size:14px}.ds-shortlist-detail>span{font-size:11px}.ds-software-monogram{width:38px;height:38px;font-size:20px;border-radius:9px}.ds-stage-note{font-size:10px;gap:8px;justify-content:space-between}.ds-stage-note svg{width:12px}}
/* One moving discovery desk; text and controls outside the panes remain still. */
.ds-shortlist-stage { --window-play-state:paused; padding-block:20px 24px; }
.ds-shortlist-stage[data-motion-running="true"] { --window-play-state:running; }
.ds-motion-toggle { display:grid; place-items:center; width:44px; height:44px; border:1px solid rgba(23,59,44,.2); border-radius:50%; flex-shrink:0; transition:background var(--duration-ui); }
.ds-motion-toggle:hover { background:rgba(255,255,255,.5); }
.ds-shortlist-tabs { margin-top:12px; }
.ds-shortlist-window-scene { position:relative; margin-top:20px; padding-bottom:116px; animation:ds-window-desk-enter 640ms var(--ease-out) both; }
.ds-shortlist-window-scene .ds-shortlist-sheet { margin-top:0; padding:20px; }
.ds-shortlist-window-scene .ds-shortlist-row { padding-block:14px; }
.ds-motion-main { animation:ds-shortlist-window-drift 8s ease-in-out infinite; animation-play-state:var(--window-play-state); }
.ds-shortlist-alternatives { position:absolute; right:-8px; bottom:8px; width:min(292px,92%); background:var(--surface); border-radius:12px; padding:16px; box-shadow:0 12px 28px rgba(23,59,44,.14); z-index:2; }
.ds-motion-alternatives { animation:ds-alternatives-window-drift 8s ease-in-out -4s infinite; animation-play-state:var(--window-play-state); }
.ds-alternatives-window-title { display:flex; align-items:center; gap:8px; font-size:11px; font-weight:600; color:var(--muted); }
.ds-alternatives-window-content { display:flex; align-items:center; gap:12px; margin-top:12px; }
.ds-alternatives-window-content .ds-software-monogram { width:34px; height:34px; border-radius:8px; }
.ds-alternatives-window-content strong { font-size:13px; font-weight:650; }
.ds-alternatives-window-content small { display:block; font-size:11px; color:var(--muted); margin-top:3px; }
.ds-alternatives-window-content>svg { margin-left:auto; flex-shrink:0; }
.ds-shortlist-alternatives:hover strong { text-decoration:underline; }
.ds-shortlist-stage .ds-stage-note { margin-top:16px; }
.ds-shortlist-stage:has(a:focus-visible) { --window-play-state:paused; }
@media(hover:hover) { .ds-shortlist-stage:hover { --window-play-state:paused; } }
@keyframes ds-window-desk-enter { from { transform:translateY(10px); opacity:.8; } to { transform:translateY(0); opacity:1; } }
@keyframes ds-shortlist-window-drift { 0%,100% { transform:translateY(0) rotate(-.3deg); } 50% { transform:translateY(-8px) rotate(.3deg); } }
@keyframes ds-alternatives-window-drift { 0%,100% { transform:translate(0,0) rotate(.7deg); } 50% { transform:translate(6px,-12px) rotate(-.6deg); } }
@media(max-width:699px) {
  .ds-shortlist-stage { padding-block:16px 20px; }
  .ds-shortlist-window-scene { padding-bottom:116px; }
  .ds-shortlist-alternatives { right:0; width:94%; }
  @keyframes ds-shortlist-window-drift { 0%,100% { transform:translateY(0); } 50% { transform:translateY(-4px); } }
  @keyframes ds-alternatives-window-drift { 0%,100% { transform:translateY(0); } 50% { transform:translateY(-6px); } }
}
@media(prefers-reduced-motion:reduce) {
  .ds-shortlist-window-scene,.ds-motion-window { animation:none !important; transform:none !important; }
  .ds-motion-toggle { display:none; }
}

.ds-shortlist-stage{font-family:var(--font-manrope,Manrope,sans-serif);letter-spacing:-.01em;color:var(--ink,#173b2c)}.ds-shortlist-stage a{color:inherit;text-decoration:none}.ds-shortlist-stage button{font:inherit;color:inherit;cursor:pointer}.ds-shortlist-tabs button{font-size:12px;font-weight:600;border:0;background:transparent}.ds-motion-toggle{background:transparent}.ds-sheet-heading h2{margin:0}.ds-shortlist-stage a:focus-visible,.ds-shortlist-stage button:focus-visible{outline:2px solid var(--ink,#173b2c);outline-offset:4px}@media(max-width:1199px){.ds-shortlist-tabs button{font-size:11px}}@media(min-width:700px) and (max-width:959px){.ds-shortlist-tabs button{font-size:13px}}@media(max-width:699px){.ds-shortlist-tabs button{font-size:11px}}@media(prefers-reduced-motion:reduce){.ds-shortlist-stage *{animation:none!important;transition:none!important}}
 .ds-shortlist-tabs button:hover{background:rgba(255,255,255,.45)}.ds-shortlist-tabs button[aria-pressed=true]{background:var(--ink);color:var(--surface)}.ds-motion-toggle:hover{background:rgba(255,255,255,.5)}

.ds-buyer-editorial { display:grid; grid-template-columns:5fr 7fr; gap:32px; }
.ds-featured-software { display:flex; flex-direction:column; padding:32px; background:var(--stage); border-radius:16px; transition:background var(--duration-ui); }
.ds-featured-software:hover { background:#d4e0c6; }
.ds-featured-software-top { display:flex; justify-content:space-between; align-items:center; margin-bottom:32px; }
.ds-featured-software .ds-software-monogram { width:48px; height:48px; }
.ds-featured-software h3 { font-size:38px; line-height:1.15; letter-spacing:-.03em; font-weight:600; }
.ds-featured-software>p { margin-top:24px; font-size:25px; line-height:1.35; letter-spacing:-.02em; max-width:25ch; }
.ds-featured-software-action { display:flex; align-items:center; justify-content:space-between; gap:16px; padding-top:48px; margin-top:auto; font-size:13px; font-weight:650; }
.ds-featured-software-action>span { font-size:12px; font-weight:400; color:var(--muted); }
.ds-buyer-tool-list { display:grid; grid-template-rows:repeat(4,1fr); }
.ds-buyer-tool-row { display:grid; grid-template-columns:44px minmax(0,1fr) 20px; gap:20px; align-items:center; min-height:108px; padding-block:20px; border-top:1px solid var(--line); transition:background var(--duration-ui); }
.ds-buyer-tool-row:last-child { border-bottom:1px solid var(--line); }
.ds-buyer-tool-row:hover { background:var(--surface-soft); }
.ds-buyer-tool-row h3 { font-size:21px; font-weight:600; line-height:1.25; letter-spacing:-.025em; }
.ds-buyer-tool-copy>p { font-size:14px; line-height:1.5; color:var(--muted); margin-top:6px; max-width:48ch; }
.ds-buyer-tool-meta { display:flex; flex-wrap:wrap; justify-content:space-between; gap:4px 16px; margin-top:8px; color:var(--muted); font-size:12px; }
.ds-matcher-strip { display:flex; justify-content:space-between; align-items:center; gap:32px; margin-top:24px; background:var(--citrine); border-radius:16px; padding:28px; }
.ds-matcher-strip h3 { font-size:29px; line-height:1.2; font-weight:550; letter-spacing:-.035em; }
.ds-matcher-strip p { font-size:14px; line-height:1.6; max-width:64ch; margin-top:8px; }
.ds-matcher-strip-action { display:flex; flex-direction:column; align-items:center; gap:12px; flex-shrink:0; }
.ds-matcher-strip .ds-design-button { min-height:48px; font-size:13px; }
.ds-matcher-strip small { font-size:12px; }
@media(max-width:959px) { .ds-buyer-editorial { grid-template-columns:1fr; } .ds-featured-software>p { max-width:36ch; } }
@media(max-width:699px) {
  .ds-featured-software { padding:24px; }
  .ds-featured-software h3 { font-size:32px; }
  .ds-featured-software>p { font-size:22px; }
  .ds-buyer-tool-row { grid-template-columns:38px minmax(0,1fr) 18px; gap:12px; padding-block:24px; }
  .ds-buyer-tool-row h3 { font-size:21px; }
  .ds-buyer-tool-copy>p { font-size:14px; }
  .ds-buyer-tool-meta { font-size:11px; }
  .ds-matcher-strip { flex-direction:column; align-items:stretch; padding:24px; gap:24px; }
  .ds-matcher-strip h3 { font-size:29px; max-width:14ch; }
  .ds-matcher-strip-action,.ds-matcher-strip .ds-design-button { width:100%; }
}

.ds-software-monogram { width:44px; height:44px; flex-shrink:0; display:grid; place-items:center; font-size:23px; font-weight:750; line-height:1; border-radius:11px; background:#e7eddf; color:#345239; }
.ds-tone-0 { background:#edf0d8; color:#667224; }
.ds-tone-1 { background:#fae4db; color:#aa4931; }
.ds-tone-2 { background:#e3eaf1; color:#365d7a; }
.ds-tone-3 { background:#e8e3f1; color:#665080; }
.ds-tone-4 { background:#e7e9df; color:#334238; }
.ds-product-category { display:block; font-size:12px; color:var(--muted); margin-top:6px; }
.ds-design-button { display:inline-flex; align-items:center; justify-content:center; gap:20px; min-height:56px; padding:16px 24px; border-radius:var(--radius-control); background:var(--ink); color:var(--surface); font-size:14px; font-weight:650; line-height:1.2; transition:background var(--duration-ui),box-shadow var(--duration-ui); }
.ds-design-button:hover { background:#28543e; }
